/* Reporting: the tabs of the page (Reports and History) and History, every report generated by hand or on its schedule,
   with its progress, files, preview and actions. It loads the state of the page (/api/reporting/state) and shares it
   with the Reports tab (the event reporting:state). */
(() => {
  'use strict';

  const page = document.getElementById('report-jobs');
  if (!page) return;
  const $ = (id) => document.getElementById(id);
  const node = (tag, text, className) => {
    const element = document.createElement(tag);
    if (text !== undefined && text !== null) element.textContent = text;
    if (className) element.className = className;
    return element;
  };
  const api = async (url, init = {}) => {
    const response = await fetch(url, {credentials: 'same-origin', ...init,
      headers: init.body ? {'Content-Type': 'application/json', ...(init.headers || {})} : init.headers});
    const payload = await response.json().catch(() => ({}));
    if (!response.ok) throw new Error(typeof payload.detail === 'string' ? payload.detail : 'The request failed.');
    return payload;
  };
  const STATUS_LABELS = {queued: 'Queued', running: 'Running', stopping: 'Stopping', sent: 'Sent', completed: 'Ready',
    partial: 'Partial', failed: 'Failed', stopped: 'Stopped'};
  // Runs waiting, running or finishing the step they are on after a user stopped them; those Stop and Rerun act on.
  const ACTIVE = ['queued', 'running', 'stopping'];
  const STOPPABLE = ['queued', 'running'];
  const RERUNNABLE = ['failed', 'stopped'];
  const FORMATS = {pptx: ['PowerPoint', 'rp-file-pptx'], docx: ['Word', 'rp-file-docx'], xlsx: ['Excel', 'rp-file-xlsx']};
  const TAB_KEY = 'reporting:tab';

  let state = {reports: [], runs: [], can_edit: false};
  let pollTimer = 0;
  const checked = new Set();

  const status = (message, tone = '') => {
    const element = $('rp-history-status');
    element.textContent = message || '';
    element.dataset.tone = tone;
  };
  const localTime = (value) => {
    if (!value) return '—';
    const parsed = new Date(value);
    return Number.isNaN(parsed.getTime()) ? String(value) : parsed.toLocaleString(undefined, {dateStyle: 'medium', timeStyle: 'short'});
  };
  // The day of a date (YYYY-MM-DD, local time), by which the Started column filters as in Excel.
  const dayKey = (date) => `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}-${String(date.getDate()).padStart(2, '0')}`;
  const formatSize = (bytes) => {
    const units = ['B', 'KB', 'MB', 'GB'];
    let value = Number(bytes) || 0;
    let unit = 0;
    while (value >= 1024 && unit < units.length - 1) { value /= 1024; unit += 1; }
    return `${value >= 100 || unit === 0 ? Math.round(value) : value.toFixed(1)} ${units[unit]}`;
  };
  // How long a finished run took: "45 s", "3 min 12 s" or "1 h 05 min".
  const runDuration = (run) => {
    const start = Date.parse(run.started_at || ''); const end = Date.parse(run.finished_at || '');
    if (Number.isNaN(start) || Number.isNaN(end) || end < start) return '';
    const seconds = Math.round((end - start) / 1000);
    if (seconds < 60) return `${seconds} s`;
    if (seconds < 3600) return `${Math.floor(seconds / 60)} min ${String(seconds % 60).padStart(2, '0')} s`;
    return `${Math.floor(seconds / 3600)} h ${String(Math.floor(seconds / 60) % 60).padStart(2, '0')} min`;
  };
  const statusBadge = (run) => {
    const badge = node('span', STATUS_LABELS[run.status] || run.status, `rj-status rj-status-${run.status}`);
    badge.title = run.error || run.message || '';
    return badge;
  };
  const confirmed = async (title, html, label) => (typeof window.showConfirmDialog === 'function'
    ? Boolean(await window.showConfirmDialog('', {title, copyHtml: html, confirmLabel: label, cancelLabel: 'Cancel'}))
    : window.confirm(title));
  const escapeText = (value) => String(value ?? '').replace(/[&<>"']/g, (character) => (
    {'&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'}[character]));

  // -- tabs -------------------------------------------------------------------------------------
  // Reports and History, one at a time; the tab chosen is kept in the address (#history) and in this browser.
  function showTab(name, {remember = true} = {}) {
    const tab = name === 'history' ? 'history' : 'reports';
    document.querySelectorAll('[data-rp-tab]').forEach((button) => button.setAttribute('aria-selected', String(button.dataset.rpTab === tab)));
    $('rp-reports').hidden = tab !== 'reports';
    $('rp-history').hidden = tab !== 'history';
    page.dataset.tab = tab;
    if (remember) {
      try { localStorage.setItem(TAB_KEY, tab); } catch {}
      if (hashTab() !== tab) history.replaceState(null, '', `#${tab}`);
    }
  }
  document.querySelectorAll('[data-rp-tab]').forEach((button) => button.addEventListener('click', () => showTab(button.dataset.rpTab)));
  $('rp-tabs').addEventListener('keydown', (event) => {
    if (!['ArrowLeft', 'ArrowRight'].includes(event.key)) return;
    showTab(page.dataset.tab === 'history' ? 'reports' : 'history');
    document.querySelector(`[data-rp-tab="${page.dataset.tab}"]`)?.focus();
  });
  // (#reports and #history, and the sections of the menu of the module, #section-reports and #section-history.)
  const hashTab = () => /^#(?:section-)?(reports|history)$/.exec(window.location.hash)?.[1] || '';
  window.addEventListener('hashchange', () => { if (hashTab()) showTab(hashTab()); });
  window.reportingShowTab = showTab;
  showTab(hashTab() || (() => { try { return localStorage.getItem(TAB_KEY) || 'reports'; } catch { return 'reports'; } })(), {remember: false});

  // -- History ----------------------------------------------------------------------------------
  const table = $('rp-runs');
  const body = table.tBodies[0];
  const rows = () => [...body.querySelectorAll('tr[data-run-id]')];
  const filtersScope = `${page.dataset.workspaceId || ''}:${document.body.dataset.authenticatedUser || ''}`;
  const filters = window.enableExcelColumnFilters?.(table, {
    rowSelector: 'tr[data-run-id]', menuClass: 'rj-column-filter-menu',
    persistKey: `drivetest-analyzer:reporting:history-filters:${filtersScope}`,
    onChange: () => { applyFilters(); syncBulk(); },
  });
  function applyFilters() {
    const all = rows();
    all.forEach((row) => {
      row.hidden = !(filters?.matches(row) ?? true);
      if (row.hidden) {
        checked.delete(Number(row.dataset.runId));
        const box = row.querySelector('[data-run-check]');
        if (box) box.checked = false;
      }
    });
    // A day without runs shown hides its heading.
    body.querySelectorAll('tr.rp-day').forEach((day) => {
      let next = day.nextElementSibling;
      let shown = false;
      while (next && !next.classList.contains('rp-day')) { if (!next.hidden && next.dataset.runId) shown = true; next = next.nextElementSibling; }
      day.hidden = !shown;
    });
    const count = $('rp-runs-count');
    count.hidden = !filters?.activeCount();
    count.textContent = `Showing ${all.filter((row) => !row.hidden).length} of ${all.length} runs`;
  }

  // The files of a run, each in the colour of its format, linked to its download.
  function filesOf(run) {
    const list = node('ul', undefined, 'rp-files');
    run.artifacts.forEach((item, index) => {
      if (item.status === 'ready' && item.available === false) return;
      const entry = node('li');
      if (item.status !== 'ready') {
        entry.append(node('span', `${item.title || 'File'}: ${item.error || 'failed'}`, 'rj-error'));
      } else {
        const extension = String(item.file_name || '').split('.').pop().toLowerCase();
        const [label, className] = FORMATS[extension] || [extension.toUpperCase() || 'File', 'rp-file-other'];
        const link = node('a', undefined, `rp-file ${className}`);
        link.href = `/api/reporting/runs/${run.id}/artifacts/${index}`;
        link.title = item.file_name;
        link.append(node('strong', label), node('span', formatSize(item.size), 'rp-file-size'));
        entry.append(link);
      }
      list.append(entry);
    });
    return list;
  }

  const actionButton = (label, title, handler, className) => {
    const button = node('button', label, `icon-action ${className}`);
    button.type = 'button';
    button.title = title;
    button.setAttribute('aria-label', title);
    button.addEventListener('click', handler);
    return button;
  };
  const runList = (runs) => `<ul>${runs.map((run) => `<li><strong>${escapeText(run.task_name)}</strong> · run #${run.id}</li>`).join('')}</ul>`;
  const runsText = (count) => `${count} run${count === 1 ? '' : 's'}`;

  function runRow(run) {
    const row = node('tr');
    row.dataset.runId = run.id;
    const report = state.reports.find((item) => item.id === run.report_id);
    const runCell = node('td', undefined, 'rj-run-id');
    runCell.dataset.label = 'Run';
    if (state.can_edit) {
      const box = node('input');
      box.type = 'checkbox';
      box.dataset.runCheck = '';
      box.checked = checked.has(run.id);
      box.setAttribute('aria-label', `Select run #${run.id}`);
      box.addEventListener('change', () => { if (box.checked) checked.add(run.id); else checked.delete(run.id); syncBulk(); });
      runCell.append(box);
    }
    runCell.append(node('span', `#${run.id}`));
    const nameCell = node('td', undefined, 'rp-run-report');
    nameCell.dataset.label = 'Report';
    nameCell.dataset.filterValue = run.task_name;
    if (report) nameCell.append(window.reportingLabels?.(report.labels) || '');
    nameCell.append(node('span', run.task_name, 'rp-run-name'));
    const trigger = node('td', run.trigger === 'schedule' ? 'Scheduled' : `Generated by ${run.requested_by}`);
    trigger.dataset.label = 'Trigger';
    trigger.dataset.filterValue = run.trigger === 'schedule' ? 'Scheduled' : `Generated by ${run.requested_by}`;
    const started = node('td', localTime(run.started_at || run.created_at));
    started.dataset.label = 'Started';
    const startedAt = new Date(run.started_at || run.created_at || '');
    if (!Number.isNaN(startedAt.getTime())) started.dataset.filterDate = dayKey(startedAt);
    const statusCell = node('td', undefined, 'rp-run-status');
    statusCell.dataset.label = 'Status';
    statusCell.dataset.filterValue = STATUS_LABELS[run.status] || run.status;
    statusCell.append(statusBadge(run));
    const active = ACTIVE.includes(run.status);
    if (active) {
      const progress = node('span', undefined, 'rp-progress');
      progress.append(node('i'));
      progress.firstChild.style.width = `${Math.max(2, run.progress || 0)}%`;
      statusCell.append(progress, node('small', `${run.progress || 0}% · ${run.message || ''}`));
    } else if (runDuration(run)) {
      statusCell.append(node('small', ` in ${runDuration(run)}`, 'rj-duration'));
    }
    if (run.status === 'stopped' && run.message) statusCell.append(node('small', ` ${run.message}`));
    if (!active && run.error) statusCell.append(node('small', ` ${run.error}`, 'rj-error'));
    const email = node('td', run.send_email ? (run.email_status || 'Pending') : 'No email');
    email.dataset.label = 'Email';
    const files = node('td');
    files.dataset.label = 'Files';
    files.append(filesOf(run));
    files.dataset.filterValues = JSON.stringify([...new Set(run.artifacts.filter((item) => item.status === 'ready')
      .map((item) => (FORMATS[String(item.file_name || '').split('.').pop().toLowerCase()] || ['File'])[0]))]);
    const size = node('td', run.artifacts_size ? formatSize(run.artifacts_size) : '—', 'rj-size');
    size.dataset.label = 'Size';
    size.title = 'Size of all the files of this run';
    const actions = node('div', undefined, 'table-actions rp-run-actions');
    if (run.has_preview && !active) {
      const preview = node('button', 'Preview', 'rp-preview-action');
      preview.type = 'button';
      preview.title = 'Open the preview of this report, page by page';
      preview.addEventListener('click', () => window.openReportRun?.(run.id));
      actions.append(preview);
    } else if (active) {
      const follow = node('button', 'Follow', 'rp-preview-action');
      follow.type = 'button';
      follow.title = 'Follow the generation of this report';
      follow.addEventListener('click', () => window.openReportRun?.(run.id));
      actions.append(follow);
    }
    if (run.artifacts.some((item) => item.status === 'ready' && item.available !== false)) {
      const link = node('a', '⇣', 'icon-action rp-download');
      link.href = `/api/reporting/runs/${run.id}/download`;
      link.title = 'Download its files in one ZIP';
      link.setAttribute('aria-label', link.title);
      actions.append(link);
    }
    if (state.can_edit && RERUNNABLE.includes(run.status)) {
      actions.append(actionButton('↻', 'Rerun: generate it again from the beginning', () => rerunRuns([run]), 'rj-rerun'));
    }
    if (state.can_edit && STOPPABLE.includes(run.status)) {
      actions.append(actionButton('■', run.status === 'queued' ? 'Stop: it does not start' : 'Stop after the step it is on', () => stopRuns([run]), 'rj-stop'));
    }
    if (state.can_edit && !active) {
      actions.append(actionButton('×', 'Delete this run and its files', () => deleteRuns([run]), 'rj-run-delete'));
    }
    const actionsCell = node('td', undefined, 'rp-actions-cell');
    actionsCell.append(actions);
    row.append(runCell, nameCell, trigger, started, statusCell, email, files, size, actionsCell);
    return row;
  }

  function renderRuns() {
    $('rp-count-history').textContent = state.runs.length ? String(state.runs.length) : '';
    if (!state.runs.length) {
      const row = node('tr');
      const cell = node('td', 'No report has been generated yet: Generate one in Reports, or give it a schedule.', 'form-note');
      cell.colSpan = 9;
      row.append(cell);
      body.replaceChildren(row);
      syncBulk();
      return;
    }
    // The runs, the latest first, under the heading of their day.
    const items = [];
    let day = '';
    state.runs.forEach((run) => {
      const date = new Date(run.started_at || run.created_at || '');
      const key = Number.isNaN(date.getTime()) ? '' : dayKey(date);
      if (key !== day) {
        day = key;
        const heading = node('tr', undefined, 'rp-day');
        const cell = node('th', key ? date.toLocaleDateString(undefined, {weekday: 'long', day: 'numeric', month: 'long', year: 'numeric'}) : 'Not started');
        cell.colSpan = 9;
        heading.append(cell);
        items.push(heading);
      }
      items.push(runRow(run));
    });
    body.replaceChildren(...items);
    applyFilters();
    syncBulk();
  }

  // -- several runs at once ----------------------------------------------------------------------
  const checkedRuns = (test) => state.runs.filter((run) => checked.has(run.id) && test(run));
  const downloadable = (run) => run.artifacts.some((item) => item.status === 'ready' && item.available !== false);
  function syncBulk() {
    $('rp-runs-bulk').hidden = !state.can_edit || !state.runs.length;
    const shown = rows().filter((row) => !row.hidden).map((row) => Number(row.dataset.runId));
    const all = $('rp-runs-select-all');
    all.checked = shown.length > 0 && shown.every((id) => checked.has(id));
    all.indeterminate = !all.checked && shown.some((id) => checked.has(id));
    const chosen = state.runs.filter((run) => checked.has(run.id));
    const set = (id, label, test) => {
      const button = $(id);
      const ok = chosen.length > 0 && chosen.every(test);
      button.disabled = !ok;
      button.textContent = ok ? `${label} (${chosen.length})` : label;
    };
    set('rp-rerun-selected', 'Rerun', (run) => RERUNNABLE.includes(run.status));
    set('rp-stop-selected', 'Stop', (run) => STOPPABLE.includes(run.status));
    set('rp-download-selected', 'Download', downloadable);
    set('rp-delete-selected', 'Delete', (run) => !ACTIVE.includes(run.status));
  }
  $('rp-runs-select-all').addEventListener('change', (event) => {
    rows().filter((row) => !row.hidden).forEach((row) => {
      const id = Number(row.dataset.runId);
      if (event.target.checked) checked.add(id); else checked.delete(id);
      const box = row.querySelector('[data-run-check]');
      if (box) box.checked = event.target.checked;
    });
    syncBulk();
  });

  async function rerunRuns(runs) {
    if (!await confirmed('Generate again', `<p>Generate ${runsText(runs.length)} again from the beginning? What they generated before is deleted.</p>${runList(runs)}`, 'Generate again')) return;
    try {
      await api('/api/reporting/runs/rerun', {method: 'POST', body: JSON.stringify({ids: runs.map((run) => run.id)})});
      status(`${runsText(runs.length)} generating again.`, 'done');
    } catch (error) { status(error.message, 'error'); }
    await refresh();
  }
  async function stopRuns(runs) {
    if (!await confirmed('Stop', `<p>Stop ${runsText(runs.length)}? A running one stops after the step it is on and keeps what it generated, without its email.</p>${runList(runs)}`, 'Stop')) return;
    try {
      await api('/api/reporting/runs/stop', {method: 'POST', body: JSON.stringify({ids: runs.map((run) => run.id)})});
      status(`${runsText(runs.length)} stopping.`, 'done');
    } catch (error) { status(error.message, 'error'); }
    await refresh();
  }
  async function deleteRuns(runs) {
    if (!await confirmed('Delete runs', `<p>Delete ${runsText(runs.length)} and their files? This cannot be undone.</p>${runList(runs)}`, 'Delete')) return;
    try {
      await api('/api/reporting/runs/delete', {method: 'POST', body: JSON.stringify({ids: runs.map((run) => run.id)})});
      runs.forEach((run) => checked.delete(run.id));
      status(`${runsText(runs.length)} deleted.`, 'done');
    } catch (error) { status(error.message, 'error'); }
    await refresh();
  }
  $('rp-rerun-selected').addEventListener('click', () => rerunRuns(checkedRuns((run) => RERUNNABLE.includes(run.status))));
  $('rp-stop-selected').addEventListener('click', () => stopRuns(checkedRuns((run) => STOPPABLE.includes(run.status))));
  $('rp-delete-selected').addEventListener('click', () => deleteRuns(checkedRuns((run) => !ACTIVE.includes(run.status))));
  $('rp-download-selected').addEventListener('click', () => {
    const ids = checkedRuns(downloadable).map((run) => `ids=${run.id}`).join('&');
    if (ids) window.location.href = `/api/reporting/runs/download?${ids}`;
  });

  // -- state --------------------------------------------------------------------------------------
  async function refresh() {
    clearTimeout(pollTimer);
    try {
      state = await api('/api/reporting/state');
      document.dispatchEvent(new CustomEvent('reporting:state', {detail: state}));
      renderRuns();
    } catch (error) {
      status(error.message, 'error');
    }
    const active = state.runs.some((run) => ACTIVE.includes(run.status));
    pollTimer = setTimeout(() => { void refresh(); }, active ? 3000 : 30000);
  }
  // The Reports tab asks for the state again after it saves, deletes or generates a report.
  document.addEventListener('reporting:refresh', () => { void refresh(); });
  window.reportingState = () => state;
  void refresh();
})();
